import { readFileSync } from 'node:fs'
import { parse, ParseError } from './parser.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'json' && mode !== 'keys') {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

const cmp = (a, b) => {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  for (let i = 0; i < x.length && i < y.length; i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}
const sortedKeys = (m) => [...m.keys()].sort(cmp)

function toJson(n, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  if (n.t === 'table') {
    if (n.m.size === 0) return '{}'
    const parts = sortedKeys(n.m).map((k) => pad + JSON.stringify(k) + ': ' + toJson(n.m.get(k), ind + 1))
    return '{\n' + parts.join(',\n') + '\n' + end + '}'
  }
  if (n.t === 'array') {
    if (n.items.length === 0) return '[]'
    return '[\n' + n.items.map((x) => pad + toJson(x, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  return JSON.stringify(n.v)
}

function listKeys(n, path, out) {
  if (n.t === 'table') {
    for (const k of sortedKeys(n.m)) {
      const p = path === null ? k : path + '.' + k
      const c = n.m.get(k)
      out.push(p + ' ' + c.t)
      listKeys(c, p, out)
    }
  } else if (n.t === 'array') {
    n.items.forEach((c, i) => {
      const p = path + '[' + i + ']'
      out.push(p + ' ' + c.t)
      listKeys(c, p, out)
    })
  }
}

let root
try {
  root = parse(readFileSync(0, 'utf8'))
} catch (e) {
  if (e instanceof ParseError) {
    process.stderr.write('error: ' + e.message + '\n')
    process.exit(2)
  }
  throw e
}
if (mode === 'json') process.stdout.write(toJson(root, 0) + '\n')
else {
  const out = []
  listKeys(root, null, out)
  process.stdout.write(out.map((l) => l + '\n').join(''))
}
